/**
 * Day 4 — Arrays Part-IV (Hashing). Original statements + reference solutions
 * for the in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 */

export default {
  section: 'Day 4: Arrays Part-IV',
  problems: [
    {
      slug: 'two-sum',
      title: 'Two Sum',
      difficulty: 'Easy',
      topic: 'Hashing',
      description: `Given an array of \`N\` integers and a target value \`K\`, find the two elements that add up to exactly \`K\`. Exactly one such pair exists, and an element cannot be used twice.

Print the **1-based** indices of the two elements with the smaller index first, separated by a space.

Input format: first line has \`N K\`, second line has the \`N\` integers.

{{EXAMPLES}}`,
      constraints: '2 <= N <= 10^5\n-10^9 <= arr[i], K <= 10^9\nExactly one valid pair exists',
      inputs: [
        '4 9\n2 7 11 15',
        '3 6\n3 2 4',
        '2 10\n5 5',
        '5 0\n1 -1 2 -2 3',
        '6 13\n4 1 8 3 6 7',
        '4 100\n10 20 30 70',
        '5 -3\n-1 -2 -1 -2 -3',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const [N, K] = lines[0].split(/\s+/).map(Number);
        const arr = lines[1].split(/\s+/).map(Number).slice(0, N);
        const seen = new Map();
        for (let j = 0; j < arr.length; j++) {
          const partner = K - arr[j];
          if (seen.has(partner)) return `${seen.get(partner) + 1} ${j + 1}`;
          if (!seen.has(arr[j])) seen.set(arr[j], j);
        }
        return '';
      },
    },
    {
      slug: 'four-sum',
      title: '4Sum (count quadruplets)',
      difficulty: 'Medium',
      topic: 'Hashing',
      description: `Given an array of \`N\` integers and a target \`K\`, count the number of **distinct value quadruplets** \`(a, b, c, d)\` such that \`a + b + c + d = K\` and the four values come from four different positions \`i < j < k < l\`.

Two quadruplets with the same four values count only once.

Input format: first line has \`N K\`, second line has the \`N\` integers.

Print the number of distinct quadruplets.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 200\n-10^9 <= arr[i], K <= 10^9',
      inputs: [
        '5 3\n1 0 -1 0 -2',
        '6 8\n2 2 2 2 2 2',
        '4 0\n0 0 0 0',
        '1 5\n5',
        '7 10\n1 2 3 4 5 6 7',
        '5 -10\n-5 -5 -5 -5 -5',
        '6 4\n0 1 2 3 4 5',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const [N, K] = lines[0].split(/\s+/).map(Number);
        const arr = lines[1].split(/\s+/).map(Number).slice(0, N).sort((a, b) => a - b);
        const seen = new Set();
        let count = 0;
        for (let i = 0; i < arr.length - 3; i++) {
          for (let j = i + 1; j < arr.length - 2; j++) {
            let lo = j + 1, hi = arr.length - 1;
            while (lo < hi) {
              const sum = arr[i] + arr[j] + arr[lo] + arr[hi];
              if (sum === K) {
                const key = `${arr[i]},${arr[j]},${arr[lo]},${arr[hi]}`;
                if (!seen.has(key)) { seen.add(key); count++; }
                lo++; hi--;
              } else if (sum < K) lo++;
              else hi--;
            }
          }
        }
        return String(count);
      },
    },
    {
      slug: 'longest-consecutive-sequence',
      title: 'Longest Consecutive Sequence',
      difficulty: 'Medium',
      topic: 'Hashing',
      description: `Given an unsorted array of \`N\` integers (with possible duplicates), find the length of the longest run of consecutive integers — values that differ by \`1\` each, such as \`100, 101, 102, 103\`.

The consecutive values do not need to appear next to each other in the array.

Input format: first line \`N\`, second line the \`N\` integers.

Print the length of the longest consecutive sequence.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n-10^9 <= arr[i] <= 10^9',
      inputs: [
        '6\n100 4 200 1 3 2',
        '1\n10',
        '5\n0 1 2 3 4',
        '7\n9 1 4 7 3 -1 0',
        '4\n1 1 1 1',
        '8\n10 5 12 3 55 30 31 32',
        '3\n-1 -2 -3',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const arr = lines[1].split(/\s+/).map(Number);
        const values = new Set(arr);
        let best = 0;
        for (const v of values) {
          if (values.has(v - 1)) continue;
          let len = 1, cur = v;
          while (values.has(cur + 1)) { cur++; len++; }
          best = Math.max(best, len);
        }
        return String(best);
      },
    },
    {
      slug: 'longest-subarray-with-sum-k',
      title: 'Longest Subarray With Given Sum K',
      difficulty: 'Medium',
      topic: 'Hashing',
      description: `Given an array of \`N\` integers and a target sum \`K\`, find the length of the **longest contiguous subarray** whose elements add up to exactly \`K\`.

If no subarray sums to \`K\`, print \`-1\`.

Input format: first line has \`N K\`, second line has the \`N\` integers.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n-10^9 <= arr[i], K <= 10^9',
      inputs: [
        '6 10\n10 2 3 4 1 5',
        '3 5\n1 2 3',
        '1 7\n7',
        '4 -1\n1 -1 2 -2',
        '7 0\n1 2 -3 3 1 -2 -1',
        '5 100\n1 1 1 1 1',
        '6 4\n2 1 1 1 1 3',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const [N, K] = lines[0].split(/\s+/).map(Number);
        const arr = lines[1].split(/\s+/).map(Number).slice(0, N);
        const firstIndex = new Map();
        let prefix = 0, best = -1;
        firstIndex.set(0, -1);
        for (let i = 0; i < arr.length; i++) {
          prefix += arr[i];
          if (firstIndex.has(prefix - K)) {
            best = Math.max(best, i - firstIndex.get(prefix - K));
          }
          if (!firstIndex.has(prefix)) firstIndex.set(prefix, i);
        }
        return String(best);
      },
    },
    {
      slug: 'count-subarrays-with-xor-k',
      title: 'Count Subarrays With Given XOR K',
      difficulty: 'Medium',
      topic: 'Hashing',
      description: `Given an array of \`N\` integers and a value \`K\`, count the number of contiguous subarrays whose XOR of all elements equals \`K\`.

Recall: \`a XOR b\` is \`1\` in each bit position where the two bits differ.

Input format: first line has \`N K\`, second line has the \`N\` integers.

Print the number of subarrays.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n0 <= arr[i], K <= 10^9',
      inputs: [
        '4 6\n4 2 2 6',
        '3 0\n1 1 1',
        '1 5\n5',
        '5 3\n1 2 3 4 5',
        '4 7\n7 7 7 7',
        '6 0\n0 0 0 0 0 0',
        '5 1\n1 2 3 4 5',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const [N, K] = lines[0].split(/\s+/).map(Number);
        const arr = lines[1].split(/\s+/).map(Number).slice(0, N);
        const counts = new Map();
        counts.set(0, 1);
        let xor = 0, total = 0;
        for (const x of arr) {
          xor ^= x;
          total += counts.get(xor ^ K) || 0;
          counts.set(xor, (counts.get(xor) || 0) + 1);
        }
        return String(total);
      },
    },
    {
      slug: 'longest-substring-without-repeating',
      title: 'Longest Substring Without Repeating Characters',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Given a string \`S\`, find the length of the longest substring that contains no character more than once.

The string contains no spaces and is given on a single line.

Input format: one line containing \`S\`.

Print the length of the longest substring with all distinct characters.

{{EXAMPLES}}`,
      constraints: '1 <= |S| <= 10^5\nS contains printable ASCII characters and no spaces',
      inputs: [
        'abcabcbb',
        'bbbbb',
        'pwwkew',
        'a',
        'abcdefg',
        'aab',
        'dvdf',
      ],
      solve(input) {
        const s = input.trim().split('\n')[0];
        const lastSeen = new Map();
        let start = 0, best = 0;
        for (let i = 0; i < s.length; i++) {
          const ch = s[i];
          if (lastSeen.has(ch) && lastSeen.get(ch) >= start) start = lastSeen.get(ch) + 1;
          lastSeen.set(ch, i);
          best = Math.max(best, i - start + 1);
        }
        return String(best);
      },
    },
  ],
};
